package com.oms.order.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.common.core.constant.SecurityConstants;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Local durable intent fences carrier edits/voids before any request can reach WMS. */
@Service
public class OrderShipmentDispatchService {
    @Resource private OrderRepository repository;
    @Resource private OrderShipmentWmsClient wms;
    @Resource private ExchangeContinuationService continuations;
    @Resource private OrderWarehouseClient inventory;
    private TransactionTemplate tx(){TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));tx.setTimeout(70);return tx;}
    private Map<String,Object> target(String company,Map<String,Object> payload){R<Map<String,Object>> response=wms.resolve(company,payload,SecurityConstants.INNER);require(response!=null,"仓库配置服务未响应");require(R.isSuccess(response),response.getMsg());require(response.getData()!=null,"仓库下发目标为空");return response.getData();}
    @SuppressWarnings("unchecked") private void sameTarget(String company,Map<String,Object> payload){Map<String,Object> now=target(company,payload),previous=(Map<String,Object>)payload.get("route");for(String field:Arrays.asList("connection_id","provider","api_version","environment","external_warehouse","external_owner"))require(text(now,field).equals(text(previous,field)),"原下发目标已变化，请恢复原仓库配置后重试");}
    Map<String,Object> lock(String company,long id,Long version,boolean sending){
        List<Map<String,Object>> keys=repository.db().query("SELECT s.order_id,s.channel_id,o.platform_order_id FROM oms_order_shipment s JOIN oms_order o ON o.company_code=s.company_code AND o.id=s.order_id WHERE s.company_code=? AND s.id=?",ROW,company,id);require(keys.size()==1,"发货单不存在或无权访问");Map<String,Object> key=keys.get(0);
        List<Map<String,Object>> shops=repository.db().query("SELECT * FROM oms_order_pull_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,key.get("channel_id"));require(shops.size()==1,"店铺接入配置不存在");if(sending)require(shops.get(0).get("lease_until")==null||time(text(shops.get(0),"lease_until")).isBefore(LocalDateTime.now()),"店铺正在处理，请稍后重试");
        List<Map<String,Object>> platforms=repository.db().query("SELECT * FROM oms_platform_order WHERE company_code=? AND id=? FOR UPDATE",ROW,company,key.get("platform_order_id"));require(platforms.size()==1,"来源平台订单不存在");Map<String,Object> platform=platforms.get(0),order=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",ROW,company,key.get("order_id")).get(0),shipment=repository.db().query("SELECT * FROM oms_order_shipment WHERE company_code=? AND id=? FOR UPDATE",ROW,company,id).get(0);
        if(version!=null)require(number(shipment,"control_version")==version,"发货单已变化，请刷新后重试");
        if(sending){if(OrderShipmentOwner.exchange(shipment)&&number(shipment,"fulfillment_round")>1)continuations.guardExecution(company,number(shipment,"exchange_id"));OrderShipmentOwner.apply(repository,company,shipment,order,platform,true);if(!OrderShipmentOwner.exchange(shipment))OrderExchangeGuard.requireReady(repository,company,number(order,"id"),true);require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=?",Long.class,company,id)==0,"发货单已有虚拟出库记录，不能下发真实WMS");require("WAIT_ALLOCATION".equals(text(order,"status"))&&"APPROVED".equals(text(order,"review_status")),"来源订单已停止履约或尚未审核");require(number(order,"manual_hold")==0,"来源订单已人工挂起");String block=OrderReviewPolicy.systemBlock(platform);require(block.isEmpty(),block);require(number(platform,"business_order_id")==number(shipment,"order_id")&&"SUCCESS".equals(text(platform,"conversion_status")),"来源订单关联不一致");require(Arrays.asList("WAIT_DISPATCH","DISPATCHING").contains(text(shipment,"status")),"当前发货单不允许下发");require("MATCHED".equals(text(shipment,"carrier_match_status"))&&!text(shipment,"warehouse_carrier_code").isEmpty(),"请先确认发货单快递与仓库快递编码");require(repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,id)==0,"已有出库数量，不能重新下发");}
        shipment.put("platform",platform);shipment.put("order",order);shipment.put("shop",shops.get(0));shipment.put("platform_order_id",key.get("platform_order_id"));return shipment;
    }
    private Object canonical(Object value){if(value instanceof Map){Map<String,Object> result=new TreeMap<>();((Map<?,?>)value).forEach((k,v)->result.put(k.toString(),canonical(v)));return result;}if(value instanceof List){List<Object> result=new ArrayList<>();for(Object v:(List<?>)value)result.add(canonical(v));return result;}return value;}
    @SuppressWarnings("unchecked") private Map<String,Object> payload(String company,Map<String,Object> shipment){
        Map<String,Object> platform=(Map<String,Object>)shipment.get("platform"),order=(Map<String,Object>)shipment.get("order"),shop=(Map<String,Object>)shipment.get("shop");JsonNode trade;try{trade=JSON.readTree(text(platform,"processing_payload")).path("trade_fullinfo_get_response").path("trade");}catch(Exception e){throw new IllegalArgumentException("来源订单地址快照无法解析");}require(trade.isObject(),"来源订单地址快照缺失");
        List<Map<String,Object>> lines=OrderShipmentSources.lines(repository,company,number(shipment,"id"),true);require(!lines.isEmpty()&&lines.size()<=500,"发货单明细须为1至500行");require(lines.stream().mapToLong(l->number(l,"quantity")).sum()==number(shipment,"quantity"),"发货单明细与单据数量不一致");
        List<Map<String,Object>> receipts=OrderShipmentSources.receipts(inventory,company,shipment,lines);Map<Long,Map<String,Object>> byId=new HashMap<>();for(Map<String,Object> receipt:receipts)require(byId.put(number(receipt,"id"),receipt)==null,"仓库占用回执重复");Set<String> stores=new TreeSet<>();List<Map<String,Object>> outgoing=new ArrayList<>();
        for(Map<String,Object> line:lines){Map<String,Object> receipt=byId.get(number(line,"allocation_id"));require(receipt!=null,"发货单占用来源缺失或已释放");require(text(line,"stock_reference").equals(text(receipt,"platform_tid")),"发货单库存来源引用不一致");for(String field:Arrays.asList("sku_sn","platform_oid","store_code"))require(text(line,field).equals(text(receipt,field)),"发货单与库存占用身份不一致");for(String field:Arrays.asList("quantity","batch_id","stock_source_id"))require(number(line,field)==number(receipt,field),"发货单与库存占用数量或来源不一致");require(text(shipment,"owner_code").equals(text(receipt,"owner_code"))&&text(shipment,"real_store_code").equals(text(receipt,"real_store_code")),"发货单占用货主实体仓不一致");require(!text(receipt,"batch_code").isEmpty(),"分仓库存批次编码缺失，请核对台账");stores.add(text(line,"store_code"));Map<String,Object> item=new LinkedHashMap<>();for(String field:Arrays.asList("id","sku_sn","goods_name","quantity","platform_oid","store_code","gift_plan_id","stock_reference"))item.put(field,line.get(field));item.put("batch_code",receipt.get("batch_code"));for(JsonNode source:trade.path("orders").path("order"))if(line.get("platform_oid").toString().equals(source.path("oid").asText())){item.put("spec",source.path("sku_properties_name").asText(""));break;}outgoing.add(item);}
        Map<String,Object> receiver=new LinkedHashMap<>();receiver.put("name",shipment.get("receiver_name"));receiver.put("mobile",shipment.get("receiver_phone"));receiver.put("oaid",shipment.get("oaid"));for(String[] pair:new String[][]{{"province","receiver_state"},{"city","receiver_city"},{"area","receiver_district"},{"town","receiver_town"},{"detailAddress","receiver_address"}})receiver.put(pair[0],trade.path(pair[1]).asText(""));require(!OrderCarrierPolicy.province(text(receiver,"province")).isEmpty(),"收货省份缺失或无效");require(!text(receiver,"oaid").isEmpty()||(!text(receiver,"name").isEmpty()&&!text(receiver,"mobile").isEmpty()&&!text(receiver,"detailAddress").isEmpty()),"收货信息不完整且无OAID");
        Map<String,Object> result=new LinkedHashMap<>();result.put("business_type",shipment.getOrDefault("business_type","SALE"));result.put("exchange_id",OrderShipmentOwner.exchange(shipment)?shipment.get("exchange_id"):null);result.put("source_exchange_id",shipment.get("exchange_id"));result.put("business_owner_sn",shipment.getOrDefault("owner_sn",shipment.get("order_sn")));result.put("shipment_id",shipment.get("id"));result.put("order_id",order.get("id"));result.put("order_sn",order.get("order_sn"));result.put("shipment_sn",shipment.get("shipment_sn"));for(String field:Arrays.asList("owner_code","real_store_code","platform_tid","quantity","create_time","carrier_name","carrier_code","warehouse_carrier_code"))result.put(field,shipment.get(field));result.put("place_order_time",platform.get("platform_created"));result.put("operate_time",order.get("review_at"));result.put("shop_name",shop.get("channel_name"));result.put("seller_nick",shop.get("seller_nick"));result.put("receiver",receiver);result.put("store_codes",new ArrayList<>(stores));result.put("lines",outgoing);for(String field:Arrays.asList("place_order_time","operate_time","shop_name"))require(!text(result,field).isEmpty(),"下发必需的订单时间、审核时间或店铺名称缺失");result.put("route",target(company,result));return result;
    }
    private Map<String,Object> outcome(long id,boolean success,String message){Map<String,Object> result=new LinkedHashMap<>();result.put("id",id);result.put("success",success);result.put("message",message);return result;}
    private void log(String company,Map<String,Object> shipment,String action,String result,String message,String actor){String clipped=message.substring(0,Math.min(500,message.length()));repository.db().update("INSERT INTO oms_order_shipment_log(company_code,shipment_id,action,result,message,operator_name) VALUES (?,?,?,?,?,?)",company,shipment.get("id"),action,result,clipped,actor);repository.log(company,number(shipment,"platform_order_id"),action,result,text(shipment,"shipment_sn")+"："+clipped,actor);repository.shipmentChanged(company,number(shipment,"id"));}
    private Map<String,Object> previewInfo(String company,long id){
        Map<String,Object> row=outcome(id,false,"下发条件尚未确认");
        List<Map<String,Object>> found=repository.db().query("SELECT s.shipment_sn,s.order_id,s.order_sn,s.platform_tid,s.channel_id,c.channel_name,s.owner_code,s.real_store_code,s.real_store_name,s.quantity,s.carrier_name,s.control_version FROM oms_order_shipment s LEFT JOIN oms_order_pull_config c ON c.company_code=s.company_code AND c.channel_id=s.channel_id WHERE s.company_code=? AND s.id=?",ROW,company,id);
        if(found.isEmpty())return row;row.putAll(found.get(0));
        row.put("lines",repository.db().query("SELECT l.id,l.sku_sn,l.goods_name,l.quantity,l.platform_oid,l.store_code,l.batch_id,(SELECT gl.gift_plan_id FROM oms_order_line gl WHERE gl.company_code=l.company_code AND gl.id=l.order_line_id) gift_plan_id,COALESCE(p.platform_spec,'') spec FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.id=l.shipment_id AND s.company_code=l.company_code JOIN oms_order o ON o.id=s.order_id AND o.company_code=s.company_code LEFT JOIN oms_platform_order_line p ON p.company_code=o.company_code AND p.platform_order_id=o.platform_order_id AND p.platform_oid=l.platform_oid WHERE l.company_code=? AND l.shipment_id=? ORDER BY l.id",ROW,company,id));
        return row;
    }
    @SuppressWarnings("unchecked") public List<Map<String,Object>> preview(String company,Map<String,Object> body){
        List<Map<String,Object>> result=new ArrayList<>();
        for(Map<String,Object> item:items(body)){
            long id=number(item,"id");Map<String,Object> row=previewInfo(company,id);
            try{tx().execute(s->{
                Map<String,Object> shipment=lock(company,id,number(item,"control_version"),true);
                List<Map<String,Object>> intent=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? FOR UPDATE",ROW,company,id);
                require(intent.isEmpty()||"FAILED".equals(text(intent.get(0),"state")),"已经提交下发，请先查询仓库结果");
                Map<String,Object> p=intent.isEmpty()?payload(company,shipment):decode(intent.get(0));if(!intent.isEmpty())sameTarget(company,p);
                row.putAll(outcome(id,true,intent.isEmpty()?"可提交下发":"明确下发失败，将按原下发快照重试"));
                for(String key:Arrays.asList("quantity","carrier_name","warehouse_carrier_code","lines","route"))row.put(key,p.get(key));
                row.put("snapshot_scope",intent.isEmpty()?"CURRENT":"FROZEN");row.put("retry",!intent.isEmpty());return null;
            });}catch(RuntimeException e){row.putAll(outcome(id,false,error(e,"下发条件暂未确认，请稍后重试")));}
            result.add(row);
        }
        return result;
    }
    @SuppressWarnings("unchecked") private List<Map<String,Object>> items(Map<String,Object> body){Object raw=body.get("items");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=20,"每次请选择1至20张发货单");Set<Long> seen=new HashSet<>();List<Map<String,Object>> result=new ArrayList<>();for(Object v:(List<?>)raw){require(v instanceof Map,"发货单参数无效");Map<String,Object> item=(Map<String,Object>)v;require(item.containsKey("control_version")&&number(item,"control_version")>=0&&number(item,"id")>0&&seen.add(number(item,"id")),"发货单重复或缺少版本，请刷新后重试");result.add(item);}return result;}
    public List<Map<String,Object>> submit(String company,Map<String,Object> body,String actor){List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> item:items(body)){long id=number(item,"id");try{result.add(tx().execute(s->{Map<String,Object> shipment=lock(company,id,number(item,"control_version"),true);require("WAIT_DISPATCH".equals(text(shipment,"status")),"单据已经提交或进入仓库流程，请查询仓库结果");List<Map<String,Object>> existing=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? FOR UPDATE",ROW,company,id);
                    if(existing.isEmpty()){Map<String,Object> p=payload(company,shipment);String json=encode(canonical(p));require(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=900000,"下发快照超过限制");repository.db().update("INSERT INTO oms_order_shipment_dispatch(company_code,shipment_id,shipment_sn,payload_json,payload_hash,created_by) VALUES (?,?,?,?,?,?)",company,id,shipment.get("shipment_sn"),json,hash(json),actor);}else{Map<String,Object> intent=existing.get(0);require("FAILED".equals(text(intent,"state")),"只有明确失败可以重试，结果未确认时请先查询仓库");sameTarget(company,decode(intent));repository.db().update("UPDATE oms_order_shipment_dispatch SET state='PENDING',lease_token=NULL,lease_until=NULL,next_attempt=NOW(),last_error='',query_message='',created_by=? WHERE company_code=? AND id=?",actor,company,intent.get("id"));}
                    repository.db().update("UPDATE oms_order_shipment SET status='DISPATCHING',control_version=control_version+1 WHERE company_code=? AND id=?",company,id);repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));log(company,shipment,"WMS_SUBMIT","SUCCESS","已提交仓库下发任务，快递与明细快照已固定",actor);return outcome(id,true,"已提交，等待仓库下发结果");}));}catch(RuntimeException e){result.add(outcome(id,false,error(e,"提交未确认，请刷新后核对单据状态")));}}return result;}
    @SuppressWarnings("unchecked") private Map<String,Object> decode(Map<String,Object> intent){require(hash(text(intent,"payload_json")).equals(text(intent,"payload_hash")),"下发快照校验失败，请核对原始台账");try{return JSON.readValue(text(intent,"payload_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("下发快照损坏，请核对原始台账");}}
    public Map<String,Object> query(String company,long id,String actor){return tx().execute(s->{Map<String,Object> shipment=lock(company,id,null,false);List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? FOR UPDATE",ROW,company,id);require(rows.size()==1,"该发货单尚未提交仓库");Map<String,Object> intent=rows.get(0);require(!"CANCELED".equals(text(intent,"state")),"来源单据已作废，不能继续仓库交互");require(intent.get("lease_until")==null||time(text(intent,"lease_until")).isBefore(LocalDateTime.now()),"单据正在下发或查询，请稍后刷新");String token=token();claim(company,intent,token);try{Map<String,Object> reply=data(wms.query(company,Collections.singletonMap("shipment_sn",text(shipment,"shipment_sn")),SecurityConstants.INNER));sync(company,shipment,intent,reply,token,true,actor);return reply;}catch(RuntimeException e){repository.db().update("UPDATE oms_order_shipment_dispatch SET query_message=?,last_query_at=NOW(),lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",error(e,"仓库查询未确认，请稍后核对"),company,intent.get("id"),token);return outcome(id,false,error(e,"仓库查询未确认，请稍后核对"));}});}
    private void claim(String company,Map<String,Object> intent,String token){repository.db().update("UPDATE oms_order_shipment_dispatch SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=?",token,company,intent.get("id"));}
    /** Holds the same shop/platform/order/shipment locks as holds and voids through the bounded WMS call. */
    public void process(String company,long shipmentId){tx().execute(s->{Map<String,Object> shipment=lock(company,shipmentId,null,false);List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? AND state IN ('PENDING','PROCESSING','UNKNOWN') AND next_attempt<=NOW() FOR UPDATE",ROW,company,shipmentId);if(rows.isEmpty())return null;Map<String,Object> intent=rows.get(0);if(intent.get("lease_until")!=null&&!time(text(intent,"lease_until")).isBefore(LocalDateTime.now()))return null;
            boolean query=!"PENDING".equals(text(intent,"state"));String token=token();claim(company,intent,token);
            if(!query)try{lock(company,shipmentId,null,true);}catch(IllegalArgumentException e){repository.db().update("UPDATE oms_order_shipment_dispatch SET state='PENDING',last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND),lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",error(e,"来源订单暂不允许下发"),company,intent.get("id"),token);return null;}
            try{
                repository.db().update("UPDATE oms_order_shipment_dispatch SET state='PROCESSING',attempts=attempts+1 WHERE company_code=? AND id=? AND lease_token=?",company,intent.get("id"),token);Map<String,Object> reply;
                if(query)reply=data(wms.query(company,Collections.singletonMap("shipment_sn",text(shipment,"shipment_sn")),SecurityConstants.INNER));else{Map<String,Object> body=new LinkedHashMap<>();body.put("payload",decode(intent));body.put("retry",number(intent,"attempts")>0);R<Map<String,Object>> response=wms.submit(company,body,SecurityConstants.INNER);if(response!=null&&!R.isSuccess(response)){reply=new LinkedHashMap<>();reply.put("dispatch_state","FAILED");reply.put("last_error",response.getMsg());reply.put("local_rejected",true);}else reply=data(response);}
                sync(company,shipment,intent,reply,token,query,"仓库任务");
            }catch(RuntimeException e){uncertain(company,intent,token,error(e,"仓库交互结果待确认，请查询后核对"));}
            return null;});}
    private void uncertain(String company,Map<String,Object> intent,String token,String message){repository.db().update("UPDATE oms_order_shipment_dispatch SET state='UNKNOWN',last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND),lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",message,company,intent.get("id"),token);}
    private void sync(String company,Map<String,Object> shipment,Map<String,Object> intent,Map<String,Object> reply,String token,boolean query,String actor){
        String remote=text(reply,"dispatch_state"),state;
        if("MISSING".equals(remote)){state=query&&"PENDING".equals(text(intent,"state"))&&number(intent,"attempts")==0?"PENDING":"UNKNOWN";if("UNKNOWN".equals(state))reply.put("last_error","仓库任务记录缺失，需核对原始受理结果；不能自动重新下发");}else{require(Boolean.TRUE.equals(reply.get("local_rejected"))||(number(reply,"shipment_id")==number(shipment,"id")&&text(reply,"shipment_sn").equals(text(shipment,"shipment_sn"))&&text(reply,"payload_hash").equals(text(intent,"payload_hash"))),"仓库任务身份或下发快照不一致");state="ACCEPTED".equals(remote)?"ACCEPTED":"FAILED".equals(remote)?"FAILED":"PENDING".equals(remote)?"PENDING":"UNKNOWN";}
        String error=text(reply,"last_error"),message=text(reply,"query_message");if("UNKNOWN".equals(state)&&error.isEmpty())error="仓库下发结果未确认，请查询受理记录";String nextStatus="ACCEPTED".equals(state)?"WAREHOUSE_PROCESSING":"FAILED".equals(state)?"WAIT_DISPATCH":"DISPATCHING";
        long actualShipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"));
        if(actualShipped>0){Map<String,Object> packages=repository.db().query("SELECT COUNT(*) package_count,COALESCE(SUM(quantity),0) packaged_quantity FROM oms_order_shipment_package WHERE company_code=? AND shipment_id=?",ROW,company,shipment.get("id")).get(0);message=OrderShipmentWarehouseProgress.confirmedMessage(number(shipment,"quantity"),actualShipped,number(packages,"packaged_quantity"),number(packages,"package_count"));if(!text(reply,"warehouse_status").isEmpty())message="仓库状态："+text(reply,"warehouse_status")+"；"+message;reply.put("query_message",message);}
        repository.db().update("UPDATE oms_order_shipment_dispatch SET state=?,remote_task_id=COALESCE(?,remote_task_id),external_order=IF(?='',external_order,?),warehouse_status=IF(?='',warehouse_status,?),last_error=?,query_message=?,last_query_at=IF(?,NOW(),last_query_at),next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND),lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",state,reply.get("id"),text(reply,"external_order"),text(reply,"external_order"),text(reply,"warehouse_status"),text(reply,"warehouse_status"),error,message,query,company,intent.get("id"),token);
        if(actualShipped>0)nextStatus=actualShipped>=number(shipment,"quantity")?"SHIPPED":"PART_SHIPPED";
        boolean changed=!nextStatus.equals(text(shipment,"status"));if(changed){repository.db().update("UPDATE oms_order_shipment SET status=?,control_version=control_version+1 WHERE company_code=? AND id=?",nextStatus,company,shipment.get("id"));repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));}
        if(query||!state.equals(text(intent,"state")))log(company,shipment,query?"WMS_QUERY":"WMS_DISPATCH","ACCEPTED".equals(state)?"SUCCESS":"FAILED".equals(state)?"FAILED":"PENDING",!message.isEmpty()?message:!error.isEmpty()?error:"ACCEPTED".equals(state)?"仓库已确认接收，等待出库回传":"任务已登记，等待仓库确认",actor);
        reply.put("dispatch_state",state);reply.put("message",!message.isEmpty()?message:!error.isEmpty()?error:"ACCEPTED".equals(state)?"仓库已确认接收，等待出库回传":"任务已登记，等待仓库确认");
    }
    private String error(RuntimeException e,String fallback){String text=e instanceof IllegalArgumentException?e.getMessage():fallback;if(text==null)text=fallback;return text.substring(0,Math.min(1000,text.length()));}
}
